module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiButton,\n  EuiSpacer,\n} from '../../../../src/components';\nimport {\n  EuiSeriesChart,\n  EuiLineSeries,\n  EuiBarSeries,\n  EuiSeriesChartUtils,\n} from '../../../../src/experimental';\n\nconst { SCALE } = EuiSeriesChartUtils;\nconst timestamp = Date.now();\nconst ONE_HOUR = 3600000;\n\nfunction randomizeData(size = 24, max = 15) {\n  return new Array(size)\n    .fill(0)\n    .map((d, i) => ({\n      x0: ONE_HOUR * i,\n      x: ONE_HOUR * (i + 1),\n      y: Math.floor(Math.random() * max),\n    }))\n    .map(el => ({\n      x: el.x + timestamp,\n      y: el.y,\n    }));\n}\nfunction buildData(series) {\n  const max = Math.ceil(Math.random() * 100000);\n  return new Array(series).fill(0).map(() => randomizeData(10, max));\n}\nexport default class Example extends Component {\n  state = {\n    series: 4,\n    data: buildData(4),\n  };\n  handleRandomize = () => {\n    this.setState({\n      data: buildData(this.state.series),\n    });\n  };\n  render() {\n    const { data } = this.state;\n    return (\n      <Fragment>\n        <EuiButton onClick={this.handleRandomize}>Randomize data</EuiButton>\n        <EuiSpacer size=\"xl\" />\n        <EuiSeriesChart width={600} height={200} xType={SCALE.TIME}>\n          {data.map((d, i) => (\n            <EuiBarSeries key={i} name={`Bars ${i}`} data={d} />\n          ))}\n          {data.map((d, i) => (\n            <EuiLineSeries key={i} name={`Lines ${i}`} data={d} showLineMarks={false} />\n          ))}\n        </EuiSeriesChart>\n      </Fragment>\n    );\n  }\n}\n"