module.exports = "import React, { Component, Fragment } from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\n\nimport {\n  EuiBasicTable,\n  EuiLink,\n  EuiHealth,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiSwitch,\n  EuiSpacer,\n} from '../../../../../src/components';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport class Table extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      pageIndex: 0,\n      pageSize: 5,\n      sortField: 'firstName',\n      sortDirection: 'asc',\n      selectedItems: [],\n      customHeader: true,\n      isResponsive: true,\n    };\n  }\n\n  onTableChange = ({ page = {}, sort = {} }) => {\n    const {\n      index: pageIndex,\n      size: pageSize,\n    } = page;\n\n    const {\n      field: sortField,\n      direction: sortDirection,\n    } = sort;\n\n    this.setState({\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n    });\n  };\n\n  onSelectionChange = (selectedItems) => {\n    this.setState({ selectedItems });\n  };\n\n  toggleHeader = () => {\n    this.setState(prevState => ({ customHeader: !prevState.customHeader }));\n  };\n\n  toggleResponsive = () => {\n    this.setState(prevState => ({ isResponsive: !prevState.isResponsive }));\n  };\n\n  deleteUser = user => {\n    store.deleteUsers(user.id);\n    this.setState({ selectedItems: [] });\n  };\n\n  cloneUser = user => {\n    store.cloneUser(user.id);\n    this.setState({ selectedItems: [] });\n  };\n\n  render() {\n    const {\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n      customHeader,\n      isResponsive,\n    } = this.state;\n\n    const {\n      pageOfItems,\n      totalItemCount,\n    } = store.findUsers(pageIndex, pageSize, sortField, sortDirection);\n\n    const actions = [{\n      name: 'Clone',\n      description: 'Clone this person',\n      icon: 'copy',\n      type: 'icon',\n      onClick: this.cloneUser\n    }, {\n      name: 'Delete',\n      description: 'Delete this person',\n      icon: 'trash',\n      type: 'icon',\n      color: 'danger',\n      onClick: this.deleteUser\n    }];\n\n    const columns = [{\n      field: 'firstName',\n      name: 'First Name',\n      truncateText: true,\n      sortable: true,\n      hideForMobile: customHeader,\n    }, {\n      field: 'lastName',\n      name: 'Last Name',\n      truncateText: true,\n      hideForMobile: customHeader,\n    }, {\n      field: 'firstName',\n      name: 'Full Name',\n      isMobileHeader: true,\n      sortable: true,\n      hideForMobile: !customHeader,\n      render: (name, item) => (\n        <span>{item.firstName} {item.lastName}</span>\n      ),\n    }, {\n      field: 'github',\n      name: 'Github',\n      render: (username) => (\n        <EuiLink href={`https://github.com/${username}`} target=\"_blank\">{username}</EuiLink>\n      )\n    }, {\n      field: 'dateOfBirth',\n      name: 'Date of Birth',\n      dataType: 'date',\n      render: (date) => formatDate(date, 'dobLong'),\n      sortable: true\n    }, {\n      field: 'nationality',\n      name: 'Nationality',\n      render: (countryCode) => {\n        const country = store.getCountry(countryCode);\n        return `${country.flag} ${country.name}`;\n      }\n    }, {\n      field: 'online',\n      name: 'Online',\n      dataType: 'boolean',\n      render: (online) => {\n        const color = online ? 'success' : 'danger';\n        const label = online ? 'Online' : 'Offline';\n        return <EuiHealth color={color}>{label}</EuiHealth>;\n      },\n      sortable: true\n    }, {\n      name: 'Actions',\n      actions\n    }];\n\n    const pagination = {\n      pageIndex: pageIndex,\n      pageSize: pageSize,\n      totalItemCount: totalItemCount,\n      pageSizeOptions: [3, 5, 8]\n    };\n\n    const sorting = {\n      sort: {\n        field: sortField,\n        direction: sortDirection,\n      },\n    };\n\n    const selection = {\n      selectable: (user) => user.online,\n      selectableMessage: (selectable) => !selectable ? 'User is currently offline' : undefined,\n      onSelectionChange: this.onSelectionChange\n    };\n\n    return (\n      <Fragment>\n        <EuiFlexGroup alignItems=\"center\" responsive={false}>\n          <EuiFlexItem grow={false}>\n            <EuiSwitch\n              label=\"Responsive\"\n              checked={isResponsive}\n              onChange={this.toggleResponsive}\n            />\n          </EuiFlexItem>\n          <EuiFlexItem grow={false}>\n            <EuiSwitch\n              label=\"Custom header\"\n              disabled={!isResponsive}\n              checked={isResponsive && customHeader}\n              onChange={this.toggleHeader}\n            />\n          </EuiFlexItem>\n        </EuiFlexGroup>\n\n        <EuiSpacer size=\"l\" />\n\n        <EuiBasicTable\n          items={pageOfItems}\n          itemId=\"id\"\n          columns={columns}\n          pagination={pagination}\n          sorting={sorting}\n          selection={selection}\n          isSelectable={true}\n          hasActions={true}\n          responsive={isResponsive}\n          onChange={this.onTableChange}\n        />\n      </Fragment>\n    );\n  }\n}\n"