module.exports = "import React from 'react';\n\nimport {\n  EuiFlexGrid,\n  EuiFlexItem,\n  EuiIcon,\n  EuiPanel,\n  EuiText,\n} from '../../../../src/components';\n\nconst iconTypes = [\n  'logoAPM',\n  'logoAppSearch',\n  'logoBeats',\n  'logoBusinessAnalytics',\n  'logoCloud',\n  'logoCloudEnterprise',\n  'logoElastic',\n  'logoElasticStack',\n  'logoElasticsearch',\n  'logoEnterpriseSearch',\n  'logoKibana',\n  'logoLogstash',\n  'logoMetrics',\n  'logoSiteSearch',\n  'logoXpack',\n].sort();\n\nexport default () => (\n  <EuiFlexGrid columns={4}>\n    {\n      iconTypes.map(iconType => (\n        <EuiFlexItem\n          className=\"guideDemo__icon\"\n          key={iconType}\n          style={{ width: '200px' }}\n        >\n          <EuiPanel>\n            <EuiIcon\n              type={iconType}\n              size=\"xl\"\n            />\n            <EuiText size=\"s\">\n              <p>{iconType}</p>\n            </EuiText>\n          </EuiPanel>\n        </EuiFlexItem>\n      ))\n    }\n  </EuiFlexGrid>\n);\n"