module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport moment from 'moment';\n\nimport {\n  EuiDatePicker,\n  EuiFormRow,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class extends Component {\n\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      startDate: moment()\n    };\n\n    this.handleChange = this.handleChange.bind(this);\n  }\n\n  handleChange(date) {\n    this.setState({\n      startDate: date\n    });\n  }\n\n  render() {\n    return (\n      <div>\n        <EuiFormRow label=\"US with fractional seconds\">\n          <EuiDatePicker\n            selected={this.state.startDate}\n            showTimeSelect\n            onChange={this.handleChange}\n            dateFormat=\"YYYY-MM-DD hh:mm:ss:SSS A\"\n          />\n        </EuiFormRow>\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFormRow label=\"China\">\n          <EuiDatePicker\n            selected={this.state.startDate}\n            showTimeSelect\n            onChange={this.handleChange}\n            dateFormat=\"YYYY-MM-DD hh:mm A\"\n            locale=\"zh-cn\"\n          />\n        </EuiFormRow>\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFormRow label=\"Korea\">\n          <EuiDatePicker\n            selected={this.state.startDate}\n            showTimeSelect\n            onChange={this.handleChange}\n            locale=\"ko\"\n            dateFormat=\"YYYY-MM-DD hh:mm A\"\n          />\n        </EuiFormRow>\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFormRow label=\"Germany on 24 hour clock\">\n          <EuiDatePicker\n            selected={this.state.startDate}\n            showTimeSelect\n            onChange={this.handleChange}\n            dateFormat=\"DD-MM-YYYY HH:mm\"\n            timeFormat=\"HH:mm\"\n            locale=\"de-de\"\n          />\n        </EuiFormRow>\n\n      </div>\n    );\n  }\n}\n"