module.exports = "import React, {\n  Component,\n  Fragment,\n} from 'react';\n\nimport {\n  EuiRange,\n  EuiSpacer,\n  EuiFormHelpText,\n} from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.levels = [\n      {\n        min: 0,\n        max: 600,\n        color: 'danger'\n      },\n      {\n        min: 600,\n        max: 2000,\n        color: 'success'\n      }\n    ];\n\n    this.state = {\n      value: '120',\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiRange\n          id={makeId()}\n          min={100}\n          max={200}\n          value={this.state.value}\n          onChange={this.onChange}\n          aria-label=\"Use aria labels when no actual label is in use\"\n          showLabels\n          showValue\n          name=\"firstRange\"\n        />\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiRange\n          id={makeId()}\n          min={100}\n          max={200}\n          value={this.state.value}\n          onChange={this.onChange}\n          disabled\n          aria-label=\"Use aria labels when no actual label is in use\"\n          showLabels\n        />\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiRange\n          id={makeId()}\n          min={100}\n          max={200}\n          value={this.state.value}\n          onChange={this.onChange}\n          aria-label=\"Use aria labels when no actual label is in use\"\n          showLabels\n          showInput\n          showRange\n        />\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiRange\n          id={makeId()}\n          min={0}\n          max={2000}\n          step={50}\n          value={this.state.value}\n          onChange={this.onChange}\n          aria-label=\"Use aria labels when no actual label is in use\"\n          aria-describedby=\"levelsHelp\"\n          showLabels\n          showInput\n          compressed\n          levels={this.levels}\n        />\n        <EuiFormHelpText id=\"levelsHelp\">Recommended levels are 600 and above.</EuiFormHelpText>\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiRange\n          id={makeId()}\n          min={0}\n          max={2000}\n          step={50}\n          value={this.state.value}\n          onChange={this.onChange}\n          aria-label=\"Use aria labels when no actual label is in use\"\n          showTicks\n          showRange\n          showValue\n          tickInterval={300}\n        />\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiRange\n          id={makeId()}\n          min={0}\n          max={2000}\n          step={50}\n          value={this.state.value}\n          onChange={this.onChange}\n          aria-label=\"Use aria labels when no actual label is in use\"\n          aria-describedby=\"levelsHelp\"\n          showTicks\n          showInput\n          tickInterval={500}\n          levels={this.levels}\n        />\n      </Fragment>\n    );\n  }\n}\n"