module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport moment from 'moment';\n\nimport {\n  EuiDatePicker,\n  EuiFormRow,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class extends Component {\n\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      startDate: moment(),\n      startDate2: moment(),\n      startDate3: moment().add(1, 'days'),\n      startDate4: moment().add(1, 'days'),\n      startDate5: moment(),\n    };\n\n    this.handleChange = this.handleChange.bind(this);\n    this.handleChange2 = this.handleChange2.bind(this);\n    this.handleChange3 = this.handleChange3.bind(this);\n    this.handleChange4 = this.handleChange4.bind(this);\n    this.handleChange5 = this.handleChange5.bind(this);\n  }\n\n  handleChange(date) {\n    this.setState({\n      startDate: date\n    });\n  }\n\n  handleChange2(date) {\n    this.setState({\n      startDate2: date\n    });\n  }\n\n  handleChange3(date) {\n    this.setState({\n      startDate3: date\n    });\n  }\n\n  handleChange4(date) {\n    this.setState({\n      startDate4: date\n    });\n  }\n\n  handleChange5(date) {\n    this.setState({\n      startDate5: date\n    });\n  }\n\n  isWeekday(date) {\n    const day = date.day();\n    return day !== 0 && day !== 6;\n  }\n\n  render() {\n    return (\n      <div>\n        <EuiFormRow label=\"Only allow a certain range of dates\">\n          <EuiDatePicker\n            showTimeSelect\n            selected={this.state.startDate}\n            onChange={this.handleChange}\n            minDate={moment().subtract(2, 'days')}\n            maxDate={moment().add(5, 'days')}\n          />\n        </EuiFormRow>\n\n        <EuiSpacer />\n\n        <EuiFormRow label=\"Only allow a certain range of times\">\n          <EuiDatePicker\n            showTimeSelect\n            selected={this.state.startDate2}\n            onChange={this.handleChange2}\n            minTime={moment().hours(17).minutes(0)}\n            maxTime={moment().hours(20).minutes(30)}\n          />\n        </EuiFormRow>\n\n        <EuiSpacer />\n\n        <EuiFormRow label=\"Exclude yesterday and today\">\n          <EuiDatePicker\n            showTimeSelect\n            selected={this.state.startDate3}\n            onChange={this.handleChange3}\n            excludeDates={[moment(), moment().subtract(1, 'days')]}\n          />\n        </EuiFormRow>\n\n        <EuiSpacer />\n\n        <EuiFormRow label=\"Exclude 12AM and 5PM from selection\">\n          <EuiDatePicker\n            showTimeSelect\n            selected={this.state.startDate4}\n            onChange={this.handleChange4}\n            excludeTimes={[moment().hours(0).minutes(0), moment().hours(17).minutes(0)]}\n          />\n        </EuiFormRow>\n\n        <EuiSpacer />\n\n        <EuiFormRow label=\"Filter so only weekdays are selectable\">\n          <EuiDatePicker\n            showTimeSelect\n            selected={this.state.startDate5}\n            onChange={this.handleChange5}\n            filterDate={this.isWeekday}\n          />\n        </EuiFormRow>\n\n      </div>\n    );\n  }\n}\n"