module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiHeader,\n  EuiHeaderBreadcrumbs,\n  EuiHeaderSection,\n  EuiHeaderSectionItem,\n  EuiHeaderSectionItemButton,\n  EuiHeaderLogo,\n  EuiIcon,\n} from '../../../../src/components';\n\nimport HeaderAppMenu from './header_app_menu';\nimport HeaderUserMenu from './header_user_menu';\nimport HeaderSpacesMenu from './header_spaces_menu';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n  }\n\n  renderLogo() {\n    return <EuiHeaderLogo iconType=\"logoKibana\" href=\"#\" aria-label=\"Go to home page\" />;\n  }\n\n  renderBreadcrumbs() {\n    const breadcrumbs = [\n      {\n        text: 'Management',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked management');\n        },\n        'data-test-subj': 'breadcrumbsAnimals',\n        className: 'customClass',\n      },\n      {\n        text: 'Truncation test is here for a really long item',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked truncation test');\n        },\n      },\n      {\n        text: 'hidden',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked hidden');\n        },\n      },\n      {\n        text: 'Users',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked users');\n        },\n      },\n      {\n        text: 'Create',\n      },\n    ];\n\n    return <EuiHeaderBreadcrumbs breadcrumbs={breadcrumbs} />;\n  }\n\n  renderSearch() {\n    return (\n      <EuiHeaderSectionItemButton aria-label=\"Search\">\n        <EuiIcon type=\"search\" size=\"m\" />\n      </EuiHeaderSectionItemButton>\n    );\n  }\n\n  render() {\n    return (\n      <EuiHeader>\n        <EuiHeaderSection grow={false}>\n          <EuiHeaderSectionItem border=\"right\">{this.renderLogo()}</EuiHeaderSectionItem>\n          <EuiHeaderSectionItem border=\"right\">\n            <HeaderSpacesMenu />\n          </EuiHeaderSectionItem>\n        </EuiHeaderSection>\n\n        {this.renderBreadcrumbs()}\n\n        <EuiHeaderSection side=\"right\">\n          <EuiHeaderSectionItem>{this.renderSearch()}</EuiHeaderSectionItem>\n\n          <EuiHeaderSectionItem>\n            <HeaderUserMenu />\n          </EuiHeaderSectionItem>\n\n          <EuiHeaderSectionItem>\n            <HeaderAppMenu />\n          </EuiHeaderSectionItem>\n        </EuiHeaderSection>\n      </EuiHeader>\n    );\n  }\n}\n"