module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiButton,\n  EuiContextMenu,\n  EuiIcon,\n  EuiPopover,\n  EuiText\n} from '../../../../src/components';\n\nfunction flattenPanelTree(tree, array = []) {\n  array.push(tree);\n\n  if (tree.items) {\n    tree.items.forEach(item => {\n      if (item.panel) {\n        flattenPanelTree(item.panel, array);\n        item.panel = item.panel.id;\n      }\n    });\n  }\n\n  return array;\n}\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n\n    const panelTree = {\n      id: 0,\n      title: 'View options',\n      items: [{\n        name: 'Show fullscreen',\n        icon: (\n          <EuiIcon\n            type=\"search\"\n            size=\"m\"\n          />\n        ),\n        onClick: () => { this.closePopover(); window.alert('Show fullscreen'); },\n      }, {\n        name: 'See more',\n        icon: 'plusInCircle',\n        panel: {\n          id: 1,\n          width: 400,\n          title: 'See more',\n          content: (\n            <EuiText style={{ padding: 24 }} textAlign=\"center\">\n              <p><EuiIcon type=\"faceHappy\" size=\"xxl\" /></p>\n\n              <h3>Context panels can contain anything</h3>\n              <p>\n                You can stuff just about anything into these panels. Be mindful of size though.\n                This panel is set to 400px and the height will grow as space allows.\n              </p>\n            </EuiText>\n          )\n        },\n      }],\n    };\n\n    this.panels = flattenPanelTree(panelTree);\n  }\n\n  onButtonClick = () => {\n    this.setState(prevState => ({\n      isPopoverOpen: !prevState.isPopoverOpen,\n    }));\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  render() {\n    const button = (\n      <EuiButton\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onButtonClick}\n      >\n        Click me to load mixed content menu\n      </EuiButton>\n    );\n\n    return (\n      <EuiPopover\n        id=\"contextMenu\"\n        button={button}\n        isOpen={this.state.isPopoverOpen}\n        closePopover={this.closePopover}\n        panelPaddingSize=\"none\"\n        withTitle\n        anchorPosition=\"upLeft\"\n      >\n        <EuiContextMenu\n          initialPanelId={0}\n          panels={this.panels}\n        />\n      </EuiPopover>\n    );\n  }\n}\n"