module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiToggle,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      toggleOn: false,\n    };\n  }\n\n  onToggleChange = (e) => {\n    this.setState({ toggleOn: e.target.checked });\n  }\n\n  render() {\n    return (\n      <div>\n        <EuiToggle onChange={this.onToggleChange} label=\"Is toggle on?\">\n          {this.state.toggleOn ? 'On' : 'Off'}\n        </EuiToggle>\n      </div>\n    );\n  }\n}\n"