module.exports = "import React from 'react';\n\nimport {\n  EuiButtonIcon,\n  EuiFlexGroup,\n  EuiFlexItem,\n} from '../../../../src/components';\n\nconst colors = [\n  'primary',\n  'text',\n  'subdued',\n  'success',\n  'warning',\n  'danger',\n  'disabled',\n];\n\nexport default () => (\n  <EuiFlexGroup gutterSize=\"s\" alignItems=\"center\">\n    {\n      colors.map((color) => (\n        <EuiFlexItem key={color} grow={false}>\n          <EuiButtonIcon\n            color={color}\n            onClick={() => window.alert('Button clicked')}\n            iconType=\"arrowRight\"\n            aria-label=\"Next\"\n            disabled={color === 'disabled' ? true : false}\n          />\n        </EuiFlexItem>\n      ))\n    }\n  </EuiFlexGroup>\n);\n"